import unittest
from src.retrieve import retrieve
class T(unittest.TestCase):
 def test_empty(self): self.assertEqual(retrieve('q', [], lambda x: []), [])
 def test_deduplicates_ranks_and_cites(self):
  calls=[]
  def embed(x): calls.append(x); return [1,0] if x in ('q','alpha') else [0,1]
  docs=[{'text':'beta','source':'b.md'},{'text':'alpha','source':'a.md'},{'text':'alpha','source':'a.md'}]
  out=retrieve('q',docs,embed)
  self.assertEqual(calls.count('alpha'),1); self.assertEqual(out[0]['source'],'a.md'); self.assertIn('score',out[0])

